import { readFileSync, writeFileSync } from "node:fs";
import { basename } from "node:path";
import { fileURLToPath } from "node:url";

import { buildGraph } from "../frontend/src/engine/dag.js";

const DEFAULT_OUT = fileURLToPath(new URL("../docs/artifact-arc.md", import.meta.url));
const ARTIFACT = fileURLToPath(new URL("../data/artifact.json", import.meta.url));
const HEADER =
  "<!-- Generated by scripts/emit-artifact-arc.mjs from data/artifact.json — do not edit. -->\n";

const STATIONS = [
  {
    key: "intent",
    title: "Intent",
    answers: "what the person asks for: targets, pins and component picks",
  },
  {
    key: "composition",
    title: "Composition and schedule",
    answers: "what goes in, and how the mash is run",
  },
  {
    key: "mass",
    title: "Mass and volume",
    answers: "how much, how strong, how wet: the batch solve and its losses",
  },
  {
    key: "bitterness",
    title: "Bitterness",
    answers: "how bitter, and where the bitterness comes from",
  },
  {
    key: "treatment",
    title: "Treatment",
    answers: "what is added to the water, and by which route",
  },
  {
    key: "beer",
    title: "The beer",
    answers: "what the batch turned out to be",
  },
];

const RANK = Object.fromEntries(STATIONS.map((station, index) => [station.key, index]));

const TREATMENT = new Set(["water.route", "water.pinned_ions"]);
const ALONGSIDE = new Set(["batch.brew_checklist"]);
const FERMENTATION = new Set([
  "batch.realized_fg",
  "batch.realized_abv",
  "batch.attenuation_above_cap",
]);
const CHEMISTRY =
  /^(water\.kettle_blend\.|water\.mash_adjustment\.|water\.added_lactate_ppm$|grist\.finished_beer_srm$)/;

const PROSE_FIELDS = ["discussion", "hop_strategy", "fermentation_strategy", "process_notes"];
const TREATMENT_OUTPUTS = ["prescription", "mash_additions", "sparge_additions"];

function readArtifact() {
  return JSON.parse(readFileSync(ARTIFACT, "utf8"));
}

function pin(id) {
  if (ALONGSIDE.has(id)) return "alongside";
  if (TREATMENT.has(id)) return "treatment";
  if (FERMENTATION.has(id) || CHEMISTRY.test(id)) return "beer";
  return null;
}

function baseStation(node) {
  if (node.kind === "boundary") {
    if (node.binding === "batch_sparge_solver") return "mass";
    if (node.binding === "hop_bitterness_solver") return "bitterness";
    return "treatment";
  }
  if (node.kind === "collection") return "composition";
  if (node.kind === "root" || node.kind === "choice" || node.kind === "selection") return "intent";
  return null;
}

function assign(artifact, graph) {
  const station = new Map();
  const visiting = new Set();

  function resolve(id) {
    if (station.has(id)) return station.get(id);
    const pinned = pin(id);
    if (pinned) {
      station.set(id, pinned);
      return pinned;
    }
    const node = artifact.nodes[id];
    const base = baseStation(node);
    if (base) {
      station.set(id, base);
      return base;
    }
    if (visiting.has(id)) return "intent";
    visiting.add(id);
    const upstream = (graph.adjacency[id] ?? []).map(resolve);
    const value =
      upstream.length === 0
        ? "intent"
        : upstream.sort((left, right) => RANK[right] - RANK[left])[0];
    visiting.delete(id);
    station.set(id, value);
    return value;
  }

  for (const id of Object.keys(artifact.nodes)) resolve(id);
  return station;
}

function membersByStation(artifact, station) {
  const members = Object.fromEntries([
    ...STATIONS.map((entry) => [entry.key, []]),
    ["alongside", []],
  ]);
  for (const [id, key] of station) members[key].push(id);
  for (const key of Object.keys(members)) members[key].sort();
  return members;
}

function groupMembers(key, ids, artifact) {
  const by = (predicate) => ids.filter(predicate);
  if (key === "intent") {
    return [
      ["roots", by((id) => artifact.nodes[id].kind === "root")],
      ["choices", by((id) => artifact.nodes[id].kind === "choice")],
      ["selections", by((id) => artifact.nodes[id].kind === "selection")],
      ["derived from intent", by((id) => artifact.nodes[id].kind === "derived")],
    ];
  }
  if (key === "composition") {
    return [
      ["the bill", by((id) => !id.startsWith("mash."))],
      ["the schedule", by((id) => id.startsWith("mash."))],
    ];
  }
  if (key === "mass" || key === "bitterness") {
    return [
      ["the solve", by((id) => artifact.nodes[id].kind === "boundary")],
      ["derived", by((id) => artifact.nodes[id].kind === "derived")],
    ];
  }
  if (key === "treatment") {
    return [["nodes", ids]];
  }
  if (key === "beer") {
    return [
      ["fermentation outcome", by((id) => FERMENTATION.has(id))],
      ["chemistry and colour", by((id) => CHEMISTRY.test(id))],
    ];
  }
  return [["collections", ids]];
}

function outputGroups(artifact) {
  const outputs = Object.keys(artifact.nodes["solver.water"].outputs ?? {});
  return TREATMENT_OUTPUTS.map((group) => ({
    group,
    count: outputs.filter((key) => key.startsWith(`${group}.`)).length,
  }));
}

function quoted(ids) {
  return ids.map((id) => `\`${id}\``).join(", ");
}

function stationTable(members) {
  const lines = ["| # | Station | Count | Answers |", "|---|---|---|---|"];
  STATIONS.forEach((station, index) => {
    lines.push(
      `| ${index + 1} | ${station.title} | ${members[station.key].length} | ${station.answers} |`
    );
  });
  lines.push(`| — | Alongside the arc | ${members.alongside.length} | what is written down, never solved |`);
  return lines.join("\n");
}

function memberSections(members, artifact) {
  const sections = [];
  STATIONS.forEach((station, index) => {
    sections.push(`### ${index + 1}. ${station.title} (${members[station.key].length})`);
    sections.push(["| Group | Members |", "|---|---|"].join("\n"));
    const rows = groupMembers(station.key, members[station.key], artifact).filter(
      ([, ids]) => ids.length > 0
    );
    if (rows.length === 0) {
      rows.push(["none", []]);
    }
    for (const [group, ids] of rows) {
      sections.push(`| ${group} | ${quoted(ids)} |`);
    }
    if (station.key === "treatment") {
      const groups = outputGroups(artifact)
        .map(({ group, count }) => `\`${group}\` (${count})`)
        .join(", ");
      sections.push(`| boundary outputs | ${groups} |`);
    }
    sections.push("");
  });

  sections.push(`### Alongside the arc (${members.alongside.length})`);
  sections.push(["| Group | Members |", "|---|---|"].join("\n"));
  sections.push(`| collections | ${quoted(members.alongside)} |`);
  sections.push(`| draft fields | ${quoted(PROSE_FIELDS)} |`);
  sections.push("");
  return sections.join("\n");
}

function mandatedOrder() {
  return [
    "## 2. The minimum mandated order",
    "",
    "Only the partial order is real. The boundary-to-boundary edges are:",
    "",
    "- `solver.hops` reads `solver.batch.cascade.sg_pre_boil`, `solver.batch.sg_post_boil` and `solver.batch.cascade.v_post_boil`.",
    "- `solver.water` reads `solver.batch.m_grist`, `solver.batch.cascade.v_strike`, `solver.batch.hlt.v_hlt_debt`, `solver.batch.cascade.v_sparge` and `solver.batch.mash_thickness_l_per_kg`.",
    "- Neither solver reads the other.",
    "",
    "```text",
    "sources (intent + composition)",
    "        |",
    "        v",
    "   solver.batch",
    "    |        |",
    "    v        v",
    "solver.hops  solver.water",
    "    |        |",
    "    +---+----+",
    "        v",
    "  whatever reads them",
    "```",
    "",
    "Everything else is the declared-input graph. Identity contributes no edges at all.",
    "",
  ].join("\n");
}

function impliedOrder() {
  return [
    "## 3. The implied order",
    "",
    "```text",
    "intent -> composition and schedule -> mass and volume -> bitterness -> treatment -> the beer",
    "```",
    "",
    "- **Two orders are a reading, not a fact.** Intent and composition are siblings; bitterness and treatment are siblings. The narrative orders them because authoring starts from targets and ends at the beer.",
    "- **The arc is the authoring direction.** Evaluation runs the same edges the other way: quantity to outcome.",
    "- **Identity underlies every station** and belongs to none; it is sealed at batch creation.",
    "- **The contract is canonical for the mandate.** The solve section of [`ui-contract.md`](ui-contract.md) states it; this document restates it for the reading.",
    "",
    "## 4. What it does not say",
    "",
    "The arc is an information-architecture candidate, not a constraint and not a layout. It does not decide grouping, copy, density or which pins are visible; importance is dependent-closure size, not station membership.",
    "",
  ].join("\n");
}

function derivation() {
  return [
    "## 5. How the partition is derived",
    "",
    "A node belongs to the latest station among its declared inputs. Solver nodes are pinned to their phase. The editorial overrides sit on top, because the rule alone does not produce the reading:",
    "",
    "| Override | Station | Why |",
    "|---|---|---|",
    "| `water.route`, `water.pinned_ions` | treatment | a treatment decision, not a bill |",
    "| `batch.brew_checklist` | alongside the arc | authored, never solved |",
    "| `batch.realized_fg`, `batch.realized_abv`, `batch.attenuation_above_cap` | the beer | the fermentation outcome is the finish |",
    "",
    "The chemistry and colour results are pinned to the beer station by id: the kettle blend and mash adjustment ions, added lactate, and finished beer SRM.",
    "",
  ].join("\n");
}

function render(artifact, graph) {
  const station = assign(artifact, graph);
  const members = membersByStation(artifact, station);
  return [
    HEADER,
    "# The artifact arc",
    "",
    "A reading of the DAG for information architecture: the stations a batch passes through, the order the graph mandates, and the order the authoring story implies. It is derived, not declared.",
    "",
    "## 1. Stations and members",
    "",
    stationTable(members),
    "",
    memberSections(members, artifact),
    mandatedOrder(),
    impliedOrder(),
    derivation(),
  ].join("\n");
}

function main() {
  const artifact = readArtifact();
  const graph = buildGraph(artifact);
  const text = render(artifact, graph);
  const outIndex = process.argv.indexOf("--out");
  const out = outIndex === -1 ? DEFAULT_OUT : process.argv[outIndex + 1];
  let changed = true;
  try {
    changed = readFileSync(out, "utf8") !== text;
  } catch {
    changed = true;
  }
  if (changed) writeFileSync(out, text);
  const station = assign(artifact, graph);
  const members = membersByStation(artifact, station);
  console.log(
    `artifact arc: ${changed ? "wrote" : "unchanged"} ${out} ` +
      `(${STATIONS.map((entry) => `${entry.key}: ${members[entry.key].length}`).join(", ")}, ` +
      `alongside: ${members.alongside.length})`
  );
}

if (process.argv[1] && basename(process.argv[1]) === "emit-artifact-arc.mjs") main();

export { assign, membersByStation, render };
